3. Создайте новый файл с именем `snake.h`, в котором определите структуру для хранения информации о змее:

```c
#include <SDL2/SDL.h>

typedef struct {
    SDL_Rect body[100]; // Максимум 100 сегментов
    int size;
    int x, y;
    int dirX, dirY;
} Snake;

void snake_init(Snake* s, int size, int x, int y) {
    s->size = size;
    s->x = x;
    s->y = y;
    s->dirX = 0;
    s->dirY = -1;

    for (int I = 0; I < size; i++) {
        s->body[i].x = s->x - size / 2 + i;
        s->body[i].y = s->y;
        s->body[i].w = s->body[i].h = 20;
    }
}
```

4. Создайте новый файл с именем `game.h`, в котором определите функции для управления игрой:

```c
#include <SDL2/SDL.h>
#include "snake.h"

#define BOARD_WIDTH 800
#define BOARD_HEIGHT 600
#define FOOD_SIZE 20
#define DELAY 200 // Миллисекунды между кадрами

typedef struct {
    SDL_Window* window;
    SDL_Renderer* renderer;
    SDL_Texture* boardTexture;
    SDL_Texture* foodTexture;
    Snake snake;
    int score;
    int foodX, foodY;
    Uint32 lastTick;
} Game;

void game_init(Game* g) {
    SDL_Init(SDL_INIT_VIDEO);
    SDL_CreateWindowAndRenderer(BOARD_WIDTH, BOARD_HEIGHT, 0, &g->window, &g->renderer);

    g->boardTexture = SDL_CreateTexture(g->renderer, SDL_PIXELFORMAT_RGBA8888, SDL_TEXTUREACCESS_TARGET, BOARD_WIDTH, BOARD_HEIGHT);
    SDL_SetRenderTarget(g->renderer, g->boardTexture);

    g->foodTexture = SDL_CreateTextureFromSurface(g->renderer, SDL_LoadBMP("food.bmp")); // Загрузите файл с едой

    game_new(g);
}

void game_new(Game* g) {
    snake_init(&g->snake, 3, BOARD_WIDTH / 2, BOARD_HEIGHT / 2);
    g->score = 0;
    g->foodX = rand() % (BOARD_WIDTH - FOOD_SIZE) + FOOD_SIZE / 2;
    g->foodY = rand() % (BOARD_HEIGHT - FOOD_SIZE) + FOOD_SIZE / 2;
    g->lastTick = SDL_GetTicks();
}

void game_destroy(Game* g) {
    SDL_DestroyTexture(g->boardTexture);
    SDL_DestroyTexture(g->foodTexture);
    SDL_DestroyRenderer(g->renderer);
    SDL_DestroyWindow(g->window);
    SDL_Quit();
}

void game_update(Game* g) {
    Uint32 now = SDL_GetTicks();
    if (now - g->lastTick > DELAY) {
        g->lastTick = now;

        // Обработка движения змейки
        int newX = g->snake.x + g->snake.dirX;
        int newY = g->snake.y + g->snake.dirY;

        // Проверка на выход за границы поля
        if (newX < 0 || newX >= BOARD_WIDTH || newY < 0 || newY >= BOARD_HEIGHT) {
            game_over(g);
            return;
        }

        // Проверка на столкновение с телом змейки
        for (int I = g->snake.size - 2; I >= 0; i--) {
            if (g->snake.body[i].x == newX && g->snake.body[i].y == newY) {
                game_over(g);
                return;
            }
        }

        // Проверка на поедание еды
        if (newX >= g->foodX && newX < g->foodX + FOOD_SIZE &&
            newY >= g->foodY && newY < g->foodY + FOOD_SIZE) {
            g->score++;
            g->snake.size++;
            g->foodX = rand() % (BOARD_WIDTH - FOOD_SIZE) + FOOD_SIZE / 2;
            g->foodY = rand() % (BOARD_HEIGHT - FOOD_SIZE) + FOOD_SIZE / 2;
        } else {
            // Сдвинуть змейку на один сегмент
            for (int I = g->snake.size - 1; I >= 1; i--) {
                g->snake.body[i].x = g->snake.body[i - 1].x;
                g->snake.body[i].y = g->snake.body[i - 1].y;
            }
            g->snake.body[0].x = newX;
            g->snake.body[0].y = newY;
        }
    }

    // Обновить направление движения змейки
    if (SDL_GetKeyboardState(NULL)[SDL_SCANCODE_LEFT] && g->snake.dirX != 1) {
        g->snake.dirX = -1;
        g->snake.dirY = 0;
    } else if (SDL_GetKeyboardState(NULL)[SDL_SCANCODE_RIGHT] && g->snake.dirX != -1) {
        g->snake.dirX = 1;
        g->snake.dirY = 0;
    } else if (SDL_GetKeyboardState(NULL)[SDL_SCANCODE_UP] && g->snake.dirY != 1) {
        g->snake.dirX = 0;
        g->snake.dirY = -1;
    } else if (SDL_GetKeyboardState(NULL)[SDL_SCANCODE_DOWN] && g->snake.dirY != -1) {
        g->snake.dirX = 0;
        g->snake.dirY = 1;
    }
}

void game_render(Game* g) {
    SDL_SetRenderTarget(g->renderer, NULL);

    // Отрисовка поля
    SDL_SetRenderDrawColor(g->renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(g->renderer, NULL);

    // Отрисовка змейки
    for (int I = 0; I < g->snake.size; i++) {
        SDL_SetTextureColorMod(g->renderer, 255, 255, 255);
        SDL_RenderCopy(g->renderer, NULL, &g->snake.body[i], &g->snake.body[i]);
    }

    // Отрисовка еды
    SDL_SetTextureColorMod(g->renderer, 255, 0, 0);
    SDL_RenderCopy(g->renderer, g->foodTexture, NULL, &SDL_Rect { g->foodX, g->foodY, FOOD_SIZE, FOOD_SIZE });

    // Отрисовка счета
    SDL_SetRenderDrawColor(g->renderer, 255, 255, 255, SDL_ALPHA_OPAQUE);
    SDL_RenderDrawLine(g->renderer, 5, 5, BOARD_WIDTH - 5, 5); // Вертикальная линия
    SDL_RenderDrawLine(g->renderer, 5, 5, 5, BOARD_HEIGHT - 5); // Горизонтальная линия
    SDL_RenderDrawLine(g->renderer, BOARD_WIDTH - 5, 5, BOARD_WIDTH - 5, BOARD_HEIGHT - 5); // Вертикальная линия
    SDL_RenderDrawLine(g->renderer, 5, BOARD_HEIGHT - 5, BOARD_WIDTH - 5, BOARD_HEIGHT - 5); // Горизонтальная линия
    SDL_SetTextureColorMod(g->renderer, 255, 255, 255);
    SDL_RenderCopy(g->renderer, NULL, NULL, &SDL_Rect { BOARD_WIDTH - 70, 10, 60, 20 });
    SDL_RenderCopy(g->renderer, NULL, NULL, &SDL_Rect { BOARD_WIDTH - 70, 35, g->score * 10, 10 });
}

void game_over(Game* g) {
    SDL_SetRenderTarget(g->renderer, NULL);
    SDL_SetRenderDrawColor(g->renderer, 255, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(g->renderer, NULL);
    SDL_SetTextureColorMod(g->renderer, 255, 255, 255);
    SDL_RenderDrawLine(g->renderer, 5, 5, BOARD_WIDTH - 5, 5); // Вертикальная линия
    SDL_RenderDrawLine(g->renderer, 5, 5, 5, BOARD_HEIGHT - 5); // Горизонтальная линия
    SDL_RenderDrawLine(g->renderer, BOARD_WIDTH - 5, 5, BOARD_WIDTH - 5, BOARD_HEIGHT - 5); // Вертикальная линия
    SDL_RenderDrawLine(g->renderer, 5, BOARD_HEIGHT - 5, BOARD_WIDTH - 5, BOARD_HEIGHT - 5); // Горизонтальная линия
    SDL_RenderCopy(g->renderer, NULL, NULL, &SDL_Rect { BOARD_WIDTH / 2 - 100, BOARD_HEIGHT / 2 - 50, 200, 100 });
    SDL_RenderCopy(g->renderer, NULL, NULL, &SDL_Rect { BOARD_WIDTH / 2 - 50, BOARD_HEIGHT / 2 + 30, 100, 20 });
}

void game_loop(Game* g) {
    SDL_Event e;
    while (SDL_PollEvent(&e)) {
        if (e.type == SDL_QUIT) {
            game_destroy(g);
            return;
        }
    }

    game_update(g);
    game_render(g);

    SDL_RenderPresent(g->renderer);
    SDL_SetRenderTarget(g->renderer, g->boardTexture);

    SDL_SetRenderDrawColor(g->renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(g->renderer);

    SDL_SetRenderTarget(g->renderer, NULL);
}

int main() {
    Game game;

    game_init(&game);

    while (1) {
        game_loop(&game);
    }

    game_destroy(&game);

    return 0;
}
```

